		return
	var lm = lm_script.new()
	lm.total_items_required = 2
	check("lm_can_complete_init", lm.can_complete_level() == false, "LevelManager.can_complete_level() deve restituire false all'inizio")
	lm.collect_item()
	check("lm_count_1", lm.collected_items == 1, "collect_item() deve incrementare la variabile a 1")
	lm.collect_item()
	check("lm_can_complete_2", lm.can_complete_level() == true, "can_complete_level() deve restituire true quando si raggiunge total_items_required")

	var goal_scene = load("res://objects/goal.tscn")
	check("goal_exists", goal_scene != null, "La scena res://objects/goal.tscn deve esistere")

