extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var l1 := await instantiate_scene("res://levels/level_1.tscn")
	if not check("l1_loaded", l1 != null, "La scena res://levels/level_1.tscn deve caricarsi senza errori"):
		return
	var player = l1.get_node_or_null("Player") as CharacterBody2D
	var goal = l1.get_node_or_null("Goal") as Area2D
	if not check("l1_nodes", player != null and goal != null, "level_1.tscn deve contenere i nodi Player e Goal"):
		return
	var next_path = get_prop(goal, "next_level_path", "")
	check("goal_path", next_path == "res://levels/level_2.tscn", "Il traguardo in level_1.tscn deve puntare a res://levels/level_2.tscn (invece è '%s')" % next_path)

	player.global_position = goal.global_position
	await wait_physics_frames(5)
	var current = current_scene_path()
	check("scene_changed", current == "res://levels/level_2.tscn", "Toccando il traguardo in level_1.tscn la scena deve cambiare in res://levels/level_2.tscn (attualmente: '%s')" % current)

